294	    /**
295	     * The ceiling applied to this owner's derived {@code membershipLevel}, fixed when the owner was
296	     * created: one above the maximum membershipLevel among the household members that already existed
297	     * at that time. The reported membership level is never allowed to exceed this cap. {@code null}
298	     * when the owner had no existing household member at creation, in which case no cap applies.
299	     */
300	    public Integer getMembershipLevelCap() {
301	        return this.membershipLevelCap;
302	    }
303	
304	    public void setMembershipLevelCap(Integer membershipLevelCap) {
305	        this.membershipLevelCap = membershipLevelCap;
306	    }
