308	    /**
309	     * Computes this owner's membership points for the given household size. Points start at 0 and
310	     * accumulate: 2 when an email address is present, 1 when the owner had no namesakes at creation
311	     * (namesakeCount is 0), 2 for a household of 3 or more members, and 3 for tenure of one or more
312	     * elapsed fiscal years (the number of 1-July fiscal-year boundaries between the registration date
313	     * and the current date). The household size is supplied by the caller (it is a live, non-persisted
314	     * count), so a {@code null} size contributes no household points.
315	     */
316	    public int membershipPoints(Integer householdSize) {
317	        int points = 0;
318	        if (this.email != null && !this.email.isBlank()) {
319	            points += 2;
320	        }
321	        if (this.namesakeCount != null && this.namesakeCount == 0) {
322	            points += 1;
323	        }
324	        if (householdSize != null && householdSize >= 3) {
325	            points += 2;
326	        }
327	        if (this.registrationDate != null
328	            && fiscalYear(LocalDate.now()) - fiscalYear(this.registrationDate) >= 1) {
329	            points += 3;
330	        }
331	        return points;
332	    }
333	
334	    /**
335	     * Derives this owner's numeric membership level for the given household size from its membership
336	     * points: 1 for 0-1 points, 2 for 2-3 points, 3 for 4-5 points, and 4 for 6 or more points. The
337	     * result is then capped at {@link #getMembershipLevelCap()} (the ceiling fixed at creation from
338	     * the household this owner joined): when a cap is present the level can never exceed it. No cap is
339	     * applied when the owner had no existing household member at creation.
340	     */
341	    public int membershipLevel(Integer householdSize) {
342	        int points = membershipPoints(householdSize);
343	        int level;
344	        if (points <= 1) {
345	            level = 1;
346	        }
347	        else if (points <= 3) {
348	            level = 2;
349	        }
350	        else if (points <= 5) {
351	            level = 3;
352	        }
353	        else {
354	            level = 4;
355	        }
356	        if (this.membershipLevelCap != null && level > this.membershipLevelCap) {
357	            level = this.membershipLevelCap;
358	        }
359	        return level;
360	    }
361	
362	    /**
363	     * Whether this owner has been soft-deleted. A newly created owner is not deleted; a
364	     * {@code DELETE /api/owners/{id}} flags it deleted while retaining the row. Deleted owners are
365	     * ignored by the create endpoint's duplicate and identity checks.
366	     */
367	    public boolean isDeleted() {
368	        return this.deleted;
369	    }
370	
371	    public void setDeleted(boolean deleted) {
372	        this.deleted = deleted;
373	    }
374	
375	    /**
376	     * The owner's derived identity key, used as the single basis for duplicate detection: the
377	     * lower-case hex SHA-256 digest over {@code normalizedTelephone + '|' + lowerEmail + '|' +
378	     * soundex(lastName)}, where the telephone and email components are empty when absent. Two
379	     * owners are duplicates only when their whole identity keys are equal, so any single differing
380	     * component (telephone, email or the surname's soundex) yields distinct keys and is allowed.
381	     * Derived from persisted fields, so it is not itself a persistent column.
382	     */
383	    @Transient
384	    public String getIdentityKey() {
385	        String normalizedTelephone = this.telephone == null ? "" : this.telephone;
386	        String lowerEmail = this.email == null ? "" : this.email.toLowerCase();
387	        String seed = normalizedTelephone + "|" + lowerEmail + "|" + soundex(getLastName());
388	        return HashUtils.sha256Hex(seed);
389	    }
390	
391	    /**
392	     * Computes the American Soundex code for a name: the retained first letter followed by three
393	     * digits derived from the remaining consonants (b,f,p,v-&gt;1; c,g,j,k,q,s,x,z-&gt;2; d,t-&gt;3;
394	     * l-&gt;4; m,n-&gt;5; r-&gt;6), with adjacent equal codes collapsed, h and w ignored (so they do
395	     * not separate equal codes) and vowels acting as separators, right-padded with zeros to length
396	     * four. Returns an empty string when the value is null or holds no letters, so surnames that
397	     * sound alike share a code.
398	     */
399	    public static String soundex(String value) {
400	        if (value == null) {
401	            return "";
402	        }
403	        String letters = value.toUpperCase().replaceAll("[^A-Z]", "");
404	        if (letters.isEmpty()) {
405	            return "";
406	        }
407	        StringBuilder code = new StringBuilder();
408	        code.append(letters.charAt(0));
409	        char previous = soundexDigit(letters.charAt(0));
410	        for (int i = 1; i < letters.length() && code.length() < 4; i++) {
411	            char c = letters.charAt(i);
412	            if (c == 'H' || c == 'W') {
413	                continue;
414	            }
415	            char digit = soundexDigit(c);
416	            if (digit != '0' && digit != previous) {
417	                code.append(digit);
418	            }
419	            previous = digit;
420	        }
421	        while (code.length() < 4) {
422	            code.append('0');
423	        }
424	        return code.toString();
425	    }
426	
427	    /** Maps a letter to its Soundex digit, or {@code '0'} for vowels, y, h and w. */
428	    private static char soundexDigit(char c) {
429	        return switch (c) {
430	            case 'B', 'F', 'P', 'V' -> '1';
431	            case 'C', 'G', 'J', 'K', 'Q', 'S', 'X', 'Z' -> '2';
432	            case 'D', 'T' -> '3';
433	            case 'L' -> '4';
434	            case 'M', 'N' -> '5';
435	            case 'R' -> '6';
436	            default -> '0';
437	        };
438	    }
439	
440	    /**
441	     * Establishes the effective registration date at persist time, so the create-time default
442	     * applies to any persistence path.
443	     */
444	    @PrePersist
445	    protected void defaultRegistrationDate() {
446	        resolveRegistrationDate();
447	    }
448	
449	    /**
450	     * Resolves this owner's effective registration date and stores it: the supplied value is used, or
451	     * the server's current date when none was supplied, and the result is rolled forward onto a
452	     * business day (a Saturday, Sunday or public holiday rolls forward to the next business day).
453	     * Returns the resolved date.
454	     * Idempotent, so it is safe to call from both the create flow and the persist hook.
455	     */
456	    public LocalDate resolveRegistrationDate() {
457	        LocalDate effective = this.registrationDate == null ? LocalDate.now() : this.registrationDate;
458	        this.registrationDate = toBusinessDay(effective);
459	        return this.registrationDate;
460	    }
461	
462	    /**
463	     * Derives the fiscal year that a date falls in, where each fiscal year starts on 1 July and is
464	     * identified by the calendar year in which it ends: a date from July onwards belongs to the
465	     * fiscal year ending in the following calendar year (e.g. 2 July 2026 gives 2027), while a date
466	     * from January to June belongs to the fiscal year ending in its own calendar year. Returns
467	     * {@code null} when the date is absent.
468	     */
469	    public static Integer fiscalYear(LocalDate date) {
470	        if (date == null) {
471	            return null;
472	        }
473	        return date.getMonthValue() >= Month.JULY.getValue() ? date.getYear() + 1 : date.getYear();
474	    }
475	
476	    /**
477	     * Rolls a registration date forward onto a business day: a Saturday, Sunday or listed public
478	     * holiday is advanced to the next non-holiday weekday, while any other weekday (and {@code null})
479	     * is returned unchanged. Applying this to a date that is already a business day is a no-op, so it
480	     * is safe to call more than once.
481	     */
482	    public static LocalDate toBusinessDay(LocalDate date) {
483	        if (date == null) {
484	            return null;
485	        }
486	        LocalDate result = date;
487	        while (isWeekend(result) || PUBLIC_HOLIDAYS.contains(result)) {
488	            result = result.plusDays(1);
489	        }
490	        return result;
491	    }
492	
493	    private static boolean isWeekend(LocalDate date) {
494	        return switch (date.getDayOfWeek()) {
495	            case SATURDAY, SUNDAY -> true;
496	            default -> false;
497	        };
498	    }
499	
500	    protected Set<Pet> getPetsInternal() {
501	        if (this.pets == null) {
502	            this.pets = new HashSet<>();
503	        }
504	        return this.pets;
505	    }
506	
507	    protected void setPetsInternal(Set<Pet> pets) {
508	        this.pets = pets;
509	    }
510	
511	    public List<Pet> getPets() {
512	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
513	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
514	        return Collections.unmodifiableList(sortedPets);
515	    }
516	
517	    public void setPets(List<Pet> pets) {
518	        this.pets = new HashSet<>(pets);
519	    }
520	
521	    public void addPet(Pet pet) {
522	        getPetsInternal().add(pet);
523	        pet.setOwner(this);
524	    }
525	
526	    /**
527	     * Return the Pet with the given name, or null if none found for this Owner.
528	     *
529	     * @param name to test
530	     * @return true if pet name is already in use
531	     */
532	    public Pet getPet(String name) {
533	        return getPet(name, false);
534	    }
535	
536	    /**
537	     * Return the Pet with the given name, or null if none found for this Owner.
538	     *
539	     * @param name to test
540	     * @return true if pet name is already in use
541	     */
542	    public Pet getPet(String name, boolean ignoreNew) {
543	        name = name.toLowerCase();
544	        for (Pet pet : getPetsInternal()) {
545	            if (!ignoreNew || !pet.isNew()) {
546	                String compName = pet.getName();
547	                compName = compName.toLowerCase();
548	                if (compName.equals(name)) {
549	                    return pet;
550	                }
551	            }
552	        }
553	        return null;
554	    }
555	
556	    public Pet getPet(Integer petId) {
557	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
558	    }
559	
560	    @Override
561	    public String toString() {
562	        return new ToStringCreator(this)
563	
564	            .append("id", this.getId())
565	            .append("new", this.isNew())
566	            .append("lastName", this.getLastName())
567	            .append("firstName", this.getFirstName())
568	            .append("address", this.address)
569	            .append("city", this.city)
570	            .append("telephone", this.telephone)
571	            .toString();
572	    }
573	}
