104	        String area = REGION_TIMEZONE.containsKey(formatLocality(owner)) ? "METRO" : "REGIONAL";
105	        return tier + "_" + area;
106	    }
107	
108	    /**
109	     * Fixed region-to-timezone table mapping each canonical region to its IANA timezone name.
110	     */
111	    Map<String, String> REGION_TIMEZONE = Map.of(
112	        "NSW", "Australia/Sydney",
113	        "VIC", "Australia/Melbourne",
114	        "QLD", "Australia/Brisbane");
115	
116	    /**
117	     * Derives an owner's {@code timezone} as the IANA timezone name for its locality/region, using
118	     * the fixed region-to-timezone table (NSW-&gt;Australia/Sydney, VIC-&gt;Australia/Melbourne,
119	     * QLD-&gt;Australia/Brisbane). The region is taken from {@link #formatLocality(Owner)}, so the
120	     * timezone always agrees with the reported locality. Returns {@code null} when the region is not
121	     * in the table (e.g. {@code 'UNKNOWN'}).
122	     */
123	    @Named("formatTimezone")
124	    default String formatTimezone(Owner owner) {
125	        if (owner == null) {
126	            return null;
127	        }
128	        return REGION_TIMEZONE.get(formatLocality(owner));
129	    }
130	
131	    /**
132	     * Computes an owner's membership points for the read-only {@code membershipPoints} field, using
133	     * the household size resolved onto the owner at read time. Delegates to
