35	import org.springframework.samples.petclinic.rest.api.OwnersApi;
36	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
37	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
38	import org.springframework.samples.petclinic.rest.dto.PetDto;
39	import org.springframework.samples.petclinic.rest.dto.PetFieldsDto;
40	import org.springframework.samples.petclinic.rest.dto.VisitDto;
41	import org.springframework.samples.petclinic.rest.dto.VisitFieldsDto;
42	import org.springframework.samples.petclinic.rest.validation.AddressNormalizer;
43	import org.springframework.samples.petclinic.service.ClinicService;
44	import org.springframework.security.access.prepost.PreAuthorize;
45	import org.springframework.web.bind.annotation.CrossOrigin;
46	import org.springframework.web.bind.annotation.RequestMapping;
47	import org.springframework.web.bind.annotation.RestController;
48	import org.springframework.web.util.UriComponentsBuilder;
49	
50	import jakarta.transaction.Transactional;
51	
52	/**
53	 * @author Vitaliy Fedoriv
54	 */
55	
56	@RestController
57	@CrossOrigin(exposedHeaders = "errors, content-type")
58	@RequestMapping("/api")
59	public class OwnerRestControllerV1 implements OwnersApi {
60	
61	    private static final Logger auditLogger = LoggerFactory.getLogger("AUDIT");
62	
63	    private static final Logger notifyLogger = LoggerFactory.getLogger("NOTIFY");
64	
65	    private final ClinicService clinicService;
66	
67	    private final OwnerMapper ownerMapper;
68	
69	    private final PetMapper petMapper;
70	
71	    private final VisitMapper visitMapper;
72	
73	    private final OwnerAuditEvents ownerAuditEvents;
74	
75	    public OwnerRestControllerV1(ClinicService clinicService,
76	                                 OwnerMapper ownerMapper,
77	                                 PetMapper petMapper,
78	                                 VisitMapper visitMapper,
79	                                 OwnerAuditEvents ownerAuditEvents) {
80	        this.clinicService = clinicService;
81	        this.ownerMapper = ownerMapper;
82	        this.petMapper = petMapper;
83	        this.visitMapper = visitMapper;
84	        this.ownerAuditEvents = ownerAuditEvents;
85	    }
86	
87	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
88	    @Override
89	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
90	        Collection<Owner> owners;
91	        if (lastName != null) {
92	            owners = this.clinicService.findOwnerByLastName(lastName);
93	        } else {
94	            owners = this.clinicService.findAllOwners();
95	        }
96	        if (owners.isEmpty()) {
97	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
98	        }
99	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
100	    }
101	
102	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
103	    @Override
104	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
105	        Owner owner = this.clinicService.findOwnerById(ownerId);
106	        if (owner == null) {
107	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
108	        }
109	        return new ResponseEntity<>(toOwnerDtoWithDerived(owner), HttpStatus.OK);
110	    }
111	
112	    /**
113	     * Builds the read representation of a persisted owner, populating the derived fields
114	     * ({@code householdSize}, {@code bulkSignupWarning}, {@code capacityWarning}) that are not
115	     * stored on the entity.
116	     */
117	    private OwnerDto toOwnerDtoWithDerived(Owner owner) {
118	        owner.setHouseholdSize(this.clinicService.countOwnersByHouseholdId(owner.getHouseholdId()));
119	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
120	        ownerDto.setBulkSignupWarning(isBulkSignup(owner.getRegistrationDate()));
121	        ownerDto.setCapacityWarning(isApproachingCapacity(owner.getCity()));
122	        return ownerDto;
123	    }
124	
125	    /**
126	     * Whether more than 80 owners have already been created on {@code registrationDate},
127	     * signalling a bulk-signup surge for the read-only {@code bulkSignupWarning} field.
128	     */
129	    private boolean isBulkSignup(LocalDate registrationDate) {
130	        return this.clinicService.countOwnersByRegistrationDate(registrationDate) > 80;
131	    }
132	
133	    /**
134	     * Whether {@code city} already holds between 40 and 49 owners (inclusive), signalling that it
135	     * is approaching the per-city capacity limit of 50, for the read-only {@code capacityWarning}
136	     * field. The hard rejection at 50 (see {@link #addOwner}) is unaffected.
137	     */
138	    private boolean isApproachingCapacity(String city) {
139	        int count = this.clinicService.countOwnersByCity(city);
140	        return count >= 40 && count <= 49;
141	    }
142	
143	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
144	    @Override
145	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto, String idempotencyKey) {
146	        // Idempotent replay: a repeat with an already-seen key returns the originally created
147	        // owner with 200 rather than creating (and possibly rejecting as) a duplicate.
148	        Integer existingId = this.clinicService.findOwnerIdByIdempotencyKey(idempotencyKey);
149	        if (existingId != null) {
150	            Owner existing = this.clinicService.findOwnerById(existingId);
151	            if (existing != null) {
152	                return new ResponseEntity<>(toOwnerDtoWithDerived(existing), HttpStatus.OK);
153	            }
154	        }
155	        HttpHeaders headers = new HttpHeaders();
156	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
157	        LocalDate registrationDate = owner.resolveRegistrationDate();
158	        if (this.clinicService.countOwnersByRegistrationDate(registrationDate) >= 100) {
159	            return new ResponseEntity<>(HttpStatus.TOO_MANY_REQUESTS);
160	        }
161	        if (this.clinicService.countOwnersByCity(owner.getCity()) >= 50) {
162	            return new ResponseEntity<>(HttpStatus.CONFLICT);
163	        }
164	        // The household id is deterministic: owners that share a (normalized lastName, postcode)
165	        // share it automatically. It feeds the membership-level cap and household sizing below.
166	        owner.setHouseholdId(this.clinicService.computeHouseholdId(owner));
167	        // A new owner joining an existing household (owners sharing a normalized lastName and
168	        // postcode) has its membershipLevel capped at one above the current maximum membershipLevel
169	        // among the existing household members. With no existing household member, no cap applies.
170	        owner.setMembershipLevelCap(this.clinicService.computeMembershipLevelCap(owner.getHouseholdId()));
171	        // Hard duplicate detection is consolidated into the owner's derived identity key (see
172	        // Owner#getIdentityKey): reject only when the new owner's whole key matches an existing one.
173	        // There is no separate household-duplicate 409: two owners sharing a lastName and postcode
174	        // but differing in telephone (or email) have distinct identity keys and are allowed.
175	        if (this.clinicService.existsOwnerWithIdentityKey(owner.getIdentityKey())) {
176	            return new ResponseEntity<>(HttpStatus.CONFLICT);
177	        }
178	        // Soft-match: the identity key differs, yet the surname's soundex and the postcode match an
179	        // existing owner, flagged 'possibleDuplicate'. This is exactly the same lastName/postcode,
180	        // different telephone case that is no longer a hard duplicate.
181	        Integer possibleDuplicateOf = this.clinicService.findPossibleDuplicateOwnerId(owner);
182	        owner.setPossibleDuplicate(possibleDuplicateOf != null);
183	        owner.setPossibleDuplicateOf(possibleDuplicateOf);
184	        owner.setNamesakeCount(
